fn rolling_max(numbers: Vec<i32>) -> Vec<i32> {
    let n = numbers.len();
    let mut result = Vec::with_capacity(n);

    if n == 0 {
        // If the input is empty, return an empty vector.
        return result;
    }

    // Initialize the running maximum with the first element.
    let mut current_max = numbers[0];
    result.push(current_max);

    // For each subsequent element, update the running maximum and push it.
    for &x in &numbers[1..] {
        if x > current_max {
            current_max = x;
        }
        result.push(current_max);
    }

    result
}

fn main() {
    let input = vec![3, 1, 4, 2, 5];
    let output = rolling_max(input.clone());
    println!("input:  {:?}\noutput: {:?}", input, output);
    // Expected output: [3, 3, 4, 4, 5]
}

